import {AnatomyViewer} from './viewer.mjs';
import {esc,normalize,gradeAnswer,shuffle,emptyRecord,sanitizeProgress} from './core.mjs';

const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const icons={box:'<path d="m12 3 9 5v8l-9 5-9-5V8zM3 8l9 5 9-5M12 13v8M8 5l9 5"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',columns:'<rect x="3" y="4" width="7" height="16" rx="1.5"/><rect x="14" y="4" width="7" height="16" rx="1.5"/>',chart:'<path d="M4 3v17h17M9 15v-4M14 15V7M19 15V4"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v4h16v-4"/>',bookmark:'<path d="M6 4h12v17l-6-4-6 4z"/>',expand:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/>',reset:'<path d="M4 10a8 8 0 1 1 1 7M4 4v6h6"/>',focus:'<path d="M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5"/><circle cx="12" cy="12" r="3"/>',layers:'<path d="m12 3 10 6-10 6L2 9zM2 13l10 6 10-6M2 17l10 6 10-6"/>',tag:'<path d="M3 3h8l10 10-8 8L3 11z"/><circle cx="8" cy="8" r="1"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>'};
function icon(name){return `<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.info}</svg>`;}
function fillIcons(){for(const el of $$('[data-icon]'))el.innerHTML=icon(el.dataset.icon);}
fillIcons();
const KEY='biol270-bone-lab-progress-v1';
